_service.sdl:
schema @link(url: "https://specs.apollo.dev/federation/v2.11", import: ["@external", "@key", "@requires"]) {
  query: Query
}

"""Date with time (isoformat)"""
scalar DateTime

extend type Option @key(fields: "id") {
  id: ID! @external
  strike: Float! @external
  underlyingSymbol: String! @external
  expiry: DateTime! @external
  optionType: String! @external
  price: Float! @requires(fields: "strike underlyingSymbol expiry optionType")
  delta: Float! @requires(fields: "strike underlyingSymbol expiry optionType")
  gamma: Float! @requires(fields: "strike underlyingSymbol expiry optionType")
}

type Query {
  _entities(representations: [_Any!]!): [_Entity]!
  _service: _Service!
  dummy: String!
}

scalar _Any

union _Entity = Option

type _Service {
  sdl: String!
}
